/* in_field is exactly `width` bytes, as if read off the wire (never
 * decoded/scrubbed -- these vectors call apad_text_len/apad_text_get
 * directly on raw field bytes, including malformed ones a non-conforming
 * sender could have produced). exp_len is what apad_text_len(in_field,
 * width) MUST return; exp_cstr/exp_cstr_len is the NUL-terminated buffer
 * apad_text_get(dst, dst_cap, in_field, width) MUST produce -- dst_cap is
 * generous throughout (width + 1) so these vectors test only the S2
 * text-field rule, not apad_text_get's separate dst_cap-clamping
 * contract. */
typedef struct {
    const char *name;
    const uint8_t *in_field;
    uint32_t width;
    uint32_t dst_cap;
    uint32_t exp_len;
    const uint8_t *exp_cstr;
    uint32_t exp_cstr_len;
} apad_vec_text_get;

